#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_ENTRIES 256
#define HEADER_MAGIC 0x4D455353

typedef struct {
    uint32_t magic;
    uint16_t version;
    uint16_t num_entries;
    uint32_t total_size;
    uint32_t checksum;
} __attribute__((packed)) MessageHeader;

typedef struct {
    uint16_t entry_type;
    uint16_t entry_len;
    uint32_t flags;
} __attribute__((packed)) EntryHeader;

typedef struct {
    char *data;
    size_t len;
    uint16_t type;
    uint32_t flags;
} ParsedEntry;

typedef struct {
    ParsedEntry entries[MAX_ENTRIES];
    int count;
    uint16_t version;
    bool validated;
} MessageContext;

/* Compute simple checksum over buffer */
static uint32_t compute_checksum(const uint8_t *buf, size_t len) {
    uint32_t sum = 0;
    for (size_t i = 0; i < len; i++) {
        sum = ((sum << 5) + sum) + buf[i];
    }
    return sum;
}

/* Validate that entry length is within bounds */
static bool validate_entry_length(uint16_t entry_len, size_t remaining) {
    /* Entry length must not exceed remaining buffer space */
    if ((size_t)entry_len > remaining) {
        return false;
    }
    return true;
}

/* Parse a single entry from the buffer */
static int parse_entry(const uint8_t *buf, size_t remaining,
                       ParsedEntry *out, size_t *consumed) {
    if (remaining < sizeof(EntryHeader)) {
        return -1;
    }

    const EntryHeader *eh = (const EntryHeader *)buf;
    uint16_t entry_len = eh->entry_len;

    if (!validate_entry_length(entry_len, remaining - sizeof(EntryHeader))) {
        return -1;
    }

    /* Allocate and copy entry data */
    out->data = (char *)malloc(entry_len + 1);
    if (!out->data) {
        return -1;
    }
    memcpy(out->data, buf + sizeof(EntryHeader), entry_len);
    out->data[entry_len] = '\0';
    out->len = entry_len;
    out->type = eh->entry_type;
    out->flags = eh->flags;

    *consumed = sizeof(EntryHeader) + entry_len;
    return 0;
}

/* Main message parsing function */
int parse_message(const uint8_t *input, size_t input_len, MessageContext *ctx) {
    if (!input || !ctx) return -1;

    memset(ctx, 0, sizeof(*ctx));

    if (input_len < sizeof(MessageHeader)) {
        return -1;
    }

    const MessageHeader *hdr = (const MessageHeader *)input;

    if (hdr->magic != HEADER_MAGIC) {
        return -1;
    }

    if (hdr->version < 1 || hdr->version > 3) {
        return -1;
    }
    ctx->version = hdr->version;

    /* Validate total_size against actual input */
    if (hdr->total_size != input_len) {
        return -1;
    }

    /* Verify checksum (computed over everything after the header) */
    uint32_t expected = compute_checksum(input + sizeof(MessageHeader),
                                         input_len - sizeof(MessageHeader));
    if (hdr->checksum != expected) {
        return -1;
    }

    uint16_t num_entries = hdr->num_entries;

    /* Bounds check: ensure we don't exceed our fixed array */
    if (num_entries > MAX_ENTRIES) {
        return -1;
    }

    const uint8_t *ptr = input + sizeof(MessageHeader);
    size_t remaining = input_len - sizeof(MessageHeader);

    ctx->count = 0;

    for (uint16_t i = 0; i < num_entries; i++) {
        size_t consumed = 0;
        if (parse_entry(ptr, remaining, &ctx->entries[ctx->count], &consumed) != 0) {
            /* Cleanup on failure */
            for (int j = 0; j < ctx->count; j++) {
                free(ctx->entries[j].data);
            }
            return -1;
        }
        ptr += consumed;
        remaining -= consumed;
        ctx->count++;
    }

    ctx->validated = true;
    return 0;
}

/* Merge entries of the same type into a combined buffer */
char *merge_entries_by_type(const MessageContext *ctx, uint16_t type,
                            size_t *out_len) {
    if (!ctx || !ctx->validated) return NULL;

    /* First pass: compute total length needed */
    size_t total = 0;
    int match_count = 0;
    for (int i = 0; i < ctx->count; i++) {
        if (ctx->entries[i].type == type) {
            total += ctx->entries[i].len;
            match_count++;
        }
    }

    if (match_count == 0) return NULL;

    /* Add space for separators between entries */
    size_t alloc_size = total + (match_count - 1);

    char *merged = (char *)malloc(alloc_size + 1);
    if (!merged) return NULL;

    /* Second pass: copy data with separator */
    size_t offset = 0;
    int written = 0;
    for (int i = 0; i < ctx->count; i++) {
        if (ctx->entries[i].type == type) {
            if (written > 0) {
                merged[offset] = '|';
                offset++;
            }
            memcpy(merged + offset, ctx->entries[i].data, ctx->entries[i].len);
            offset += ctx->entries[i].len;
            written++;
        }
    }
    merged[offset] = '\0';

    if (out_len) *out_len = offset;
    return merged;
}

/* Apply transformation based on entry flags */
int transform_entries(MessageContext *ctx) {
    if (!ctx || !ctx->validated) return -1;

    for (int i = 0; i < ctx->count; i++) {
        ParsedEntry *e = &ctx->entries[i];

        if (e->flags & 0x01) {
            /* Flag 0x01: uppercase transform */
            for (size_t j = 0; j < e->len; j++) {
                if (e->data[j] >= 'a' && e->data[j] <= 'z') {
                    e->data[j] -= 32;
                }
            }
        }

        if (e->flags & 0x02) {
            /* Flag 0x02: reverse the entry data */
            for (size_t j = 0; j < e->len / 2; j++) {
                char tmp = e->data[j];
                e->data[j] = e->data[e->len - 1 - j];
                e->data[e->len - 1 - j] = tmp;
            }
        }

        if (e->flags & 0x04) {
            /* Flag 0x04: XOR with version number for 'obfuscation' */
            uint8_t key = (uint8_t)ctx->version;
            for (size_t j = 0; j < e->len; j++) {
                e->data[j] ^= key;
            }
        }

        if (e->flags & 0x08) {
            /* Flag 0x08: truncate to first N bytes where N = entry_type */
            uint16_t new_len = e->type;
            if (new_len <= e->len) {
                e->len = new_len;
                e->data[new_len] = '\0';
            }
        }
    }
    return 0;
}

/* Serialize context back to wire format */
int serialize_message(const MessageContext *ctx, uint8_t *output,
                      size_t output_size, size_t *written_out) {
    if (!ctx || !ctx->validated || !output) return -1;

    /* Calculate required size */
    size_t required = sizeof(MessageHeader);
    for (int i = 0; i < ctx->count; i++) {
        required += sizeof(EntryHeader) + ctx->entries[i].len;
    }

    if (required > output_size) {
        return -1;
    }

    /* Write header placeholder */
    MessageHeader *hdr = (MessageHeader *)output;
    hdr->magic = HEADER_MAGIC;
    hdr->version = ctx->version;
    hdr->num_entries = (uint16_t)ctx->count;
    hdr->total_size = (uint32_t)required;

    /* Write entries */
    uint8_t *ptr = output + sizeof(MessageHeader);
    for (int i = 0; i < ctx->count; i++) {
        EntryHeader *eh = (EntryHeader *)ptr;
        eh->entry_type = ctx->entries[i].type;
        eh->entry_len = (uint16_t)ctx->entries[i].len;
        eh->flags = ctx->entries[i].flags;
        memcpy(ptr + sizeof(EntryHeader), ctx->entries[i].data,
               ctx->entries[i].len);
        ptr += sizeof(EntryHeader) + ctx->entries[i].len;
    }

    /* Compute and set checksum */
    hdr->checksum = compute_checksum(output + sizeof(MessageHeader),
                                      required - sizeof(MessageHeader));

    if (written_out) *written_out = required;
    return 0;
}

/* Free all allocated entry data */
void free_context(MessageContext *ctx) {
    if (!ctx) return;
    for (int i = 0; i < ctx->count; i++) {
        free(ctx->entries[i].data);
        ctx->entries[i].data = NULL;
    }
    ctx->count = 0;
    ctx->validated = false;
}

/* Process incoming message: parse, transform, re-serialize */
int process_message(const uint8_t *input, size_t input_len,
                    uint8_t *output, size_t output_size,
                    size_t *output_len) {
    MessageContext ctx;

    if (parse_message(input, input_len, &ctx) != 0) {
        return -1;
    }

    if (transform_entries(&ctx) != 0) {
        free_context(&ctx);
        return -1;
    }

    int ret = serialize_message(&ctx, output, output_size, output_len);
    free_context(&ctx);
    return ret;
}
